// Step 1: Validate and sanitize incoming claim dossier
const input = $input.first().json.body || $input.first().json;

const claimId = input.claimId || `CLM-2026-${String(Math.floor(10000 + Math.random() * 90000))}`;
const readinessScore = typeof input.readinessScore === 'number' ? input.readinessScore : 92;
const contradictions = Array.isArray(input.contradictions) ? input.contradictions : [];
const grossAmount = input.grossAmount || 85000;
const deductions = input.deductions || 6500;
const estimatedPayable = input.estimatedPayable || (grossAmount - deductions);
const customerName = input.customerName || 'Rahul Sharma';
const hospitalName = input.hospitalName || 'Apollo Hospital, Delhi';
const memberId = input.memberId || 'MEM-2024-78432';
const policyNumber = input.policyNumber || 'POL-HEALTH-001';

return [{
  json: {
    claimId,
    readinessScore,
    contradictions,
    contradictionCount: contradictions.length,
    grossAmount,
    deductions,
    estimatedPayable,
    customerName,
    hospitalName,
    memberId,
    policyNumber,
    receivedAt: new Date().toISOString()
  }
}];

// Step 2: AI Triage & Readiness Assessment
const item = $input.first().json;

let triageRoute = 'STANDARD_REVIEW';
let triageReason = 'Standard adjudication workflow for complete reimbursement packet.';
let priority = 'Medium';

if (item.contradictionCount > 0) {
  triageRoute = 'HUMAN_REVIEW';
  triageReason = `Blocking discrepancy flagged: ${item.contradictionCount} cross-document contradiction detected. Mandatory human adjudicator inspection.`;
  priority = 'Critical';
} else if (item.readinessScore >= 90) {
  triageRoute = 'FAST_TRACK';
  triageReason = `High-confidence complete dossier (Readiness: ${item.readinessScore}%). Fast-track queue eligible for expedited insurer review.`;
  priority = 'High';
}

return [{
  json: {
    ...item,
    triageRoute,
    triageReason,
    priority,
    triageScore: item.readinessScore
  }
}];

// Branch 1: Route to Human Claims Officer Desk
const item = $input.first().json;

return [{
  json: {
    ...item,
    selectedRoute: 'HUMAN_REVIEW',
    queueName: 'Human Escalation Queue',
    assignedOfficer: 'Priya Verma (Senior Claims Adjudicator)',
    officerBadge: 'Paytm Insurance Officer #9042',
    slaTarget: '4 hours',
    routingAction: 'Escalated to human adjudication desk with discrepancy audit packet.'
  }
}];

// Branch 2: Fast-Track Adjudication Queue
const item = $input.first().json;

return [{
  json: {
    ...item,
    selectedRoute: 'FAST_TRACK',
    queueName: 'Expedited Review Queue',
    assignedOfficer: 'Automated Triaged Pipeline',
    slaTarget: '24 hours',
    routingAction: 'Fast-track priority assigned for verified clinical packet.'
  }
}];

// Branch 3: Standard Review Queue
const item = $input.first().json;

return [{
  json: {
    ...item,
    selectedRoute: 'STANDARD_REVIEW',
    queueName: 'Standard Claims Queue',
    assignedOfficer: 'General Adjudication Pool',
    slaTarget: '48 business hours',
    routingAction: 'Enqueued for standard claims assessment.'
  }
}];

// Step 4: Policyholder Notification Preparation
const item = $input.first().json;

const formattedAmount = `₹${item.estimatedPayable.toLocaleString('en-IN')}`;
const messageBody = `Your claim ${item.claimId} has been submitted for insurer review. Estimated claim amount: ${formattedAmount}. Please note that this is a prototype demo estimate.`;

return [{
  json: {
    ...item,
    notification: {
      status: 'Notification Prepared — Demo',
      recipient: item.customerName,
      channel: 'SMS / In-App Message (Demo Simulation)',
      headline: 'Claim Ingestion Acknowledgment',
      message: messageBody,
      dispatchedAt: new Date().toISOString()
    }
  }
}];

// Step 5: Hospital Billing Dossier Preparation
const item = $input.first().json;

return [{
  json: {
    ...item,
    hospitalDossier: {
      status: 'Hospital Sync Payload Prepared — Demo',
      facility: item.hospitalName,
      patientMemberId: item.memberId,
      invoicedAmount: `₹${item.grossAmount.toLocaleString('en-IN')}`,
      excludedConsumables: `₹${item.deductions.toLocaleString('en-IN')}`,
      packetStatus: 'Synchronized with hospital billing desk test gateway',
      preparedAt: new Date().toISOString()
    }
  }
}];

// Step 6: Immutable Audit Record Generation
const item = $input.first().json;
const executionId = `N8N-EXEC-${Date.now().toString(36).toUpperCase()}-${Math.floor(100 + Math.random() * 900)}`;

const auditRecord = {
  executionId,
  claimId: item.claimId,
  policyNumber: item.policyNumber,
  customerName: item.customerName,
  readinessScore: item.readinessScore,
  contradictionCount: item.contradictionCount,
  selectedRoute: item.selectedRoute,
  priority: item.priority,
  workflowStatus: 'ORCHESTRATION_COMPLETED',
  timestamp: new Date().toISOString()
};

return [{
  json: {
    ...item,
    executionId,
    auditRecord
  }
}];
